// Turns either the pasted description or the fetched HTML into clean text.
// It also tries to read schema.org JobPosting data, which most job boards embed.
const body = $('Webhook').first().json.body || {};
const pasted = String(body.description || '').trim();
const base = { user_id: body.user_id, job_posting_id: body.job_posting_id || null, url: body.url || null };

const decode = (s) => String(s || '')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;|&apos;/gi, "'")
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)));

const htmlToText = (html) => decode(String(html || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<(nav|footer|header|svg)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/(p|div|li|h[1-6]|tr|section|article)>/gi, '\n')
  .replace(/<li[^>]*>/gi, '\n• ')
  .replace(/<[^>]+>/g, ' '))
  .replace(/[ \t]+/g, ' ')
  .replace(/\n\s*\n+/g, '\n\n')
  .trim();

let text = '';
let hints = { title: null, company: null, location: null };
let source = 'pasted';

if (pasted) {
  text = pasted;
} else {
  source = 'fetched';
  const res = $input.first().json || {};
  const html = typeof res.data === 'string' ? res.data : '';

  // 1) schema.org JobPosting in JSON-LD
  const blocks = [...html.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)];
  for (const m of blocks) {
    try {
      const parsed = JSON.parse(m[1].trim());
      const list = Array.isArray(parsed) ? parsed : (parsed['@graph'] || [parsed]);
      const job = list.find((x) => x && (x['@type'] === 'JobPosting' ||
        (Array.isArray(x['@type']) && x['@type'].includes('JobPosting'))));
      if (job) {
        hints.title = job.title || null;
        hints.company = (job.hiringOrganization && job.hiringOrganization.name) || null;
        const loc = Array.isArray(job.jobLocation) ? job.jobLocation[0] : job.jobLocation;
        const addr = loc && loc.address;
        hints.location = job.jobLocationType === 'TELECOMMUTE' ? 'Remote'
          : (addr ? [addr.addressLocality, addr.addressCountry].filter(Boolean).join(', ') : null);
        text = htmlToText(job.description || '');
        break;
      }
    } catch (e) { /* ignore broken JSON-LD */ }
  }

  // 2) Fall back to the visible page text
  if (text.length < 200) {
    const titleTag = (html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1];
    if (!hints.title && titleTag) hints.title = decode(titleTag).trim().slice(0, 140);
    const main = (html.match(/<main[\s\S]*?<\/main>/i) || [])[0] || html;
    text = htmlToText(main);
  }
}

text = text.slice(0, 15000);
const looksBlocked = /sign in|log in to|captcha|enable javascript|access denied/i.test(text.slice(0, 400));

if (text.length < 200 || (source === 'fetched' && looksBlocked && text.length < 800)) {
  return [{ json: { ...base, ok: false,
    error: source === 'pasted'
      ? 'The pasted description is too short. Paste the full job post text.'
      : 'This job page could not be read automatically. Sites like LinkedIn block it. Paste the job description instead.' } }];
}

return [{ json: { ...base, ok: true, source, input_method: source === 'pasted' ? 'pasted' : 'link', text, hints } }];

// Change the model here if Google renames or retires it.
const MODEL = 'gemini-2.5-flash';

const job = $('Clean Job Text').first().json;
const resumeRow = $input.first().json || {};
const resume = String(resumeRow.resume_text || '').trim();

if (!resume) {
  throw new Error('No resume found for this user. Upload a resume first.');
}

const prompt = `You are a senior technical recruiter and career coach.
Compare the candidate resume with the job post and respond with JSON only.

Scoring rubric for fit_score (0 to 100):
- 85 to 100: meets nearly all required skills and the seniority level.
- 70 to 84: meets most requirements, small gaps that are easy to explain.
- 50 to 69: meets about half, noticeable gaps.
- below 50: major gaps or a different role or seniority.
Be honest. Do not inflate the score.

Rules:
- matched_skills: skills, tools or experience that appear in BOTH the resume and the job post (max 12).
- missing_skills: requirements from the job post that the resume does not show (max 10).
- talking_points: 3 to 5 short points the candidate should stress when applying, based only on the resume.
- verdict: one of "Strong fit", "Good fit", "Stretch", "Weak fit".
- summary: two or three plain sentences explaining the score.
- company, title, location: read them from the job post. Use "Unknown" if not stated.
- cover_letter: 220 to 320 words, first person, warm and specific, addressed to the hiring team.
  Mention two or three concrete achievements from the resume that match the job.
  Never invent experience, employers, numbers or degrees that are not in the resume.
  Do not use em dashes. Do not include a subject line or placeholders like [Your Name];
  sign off with the candidate's name if the resume shows it.

Hints scraped from the page (may be empty): ${JSON.stringify(job.hints || {})}

<job_post>
${job.text}
</job_post>

<candidate_resume>
${resume.slice(0, 12000)}
</candidate_resume>`;

const str = { type: 'STRING' };
const list = { type: 'ARRAY', items: { type: 'STRING' } };

return [{ json: {
  model: MODEL,
  request: {
    contents: [{ role: 'user', parts: [{ text: prompt }] }],
    generationConfig: {
      temperature: 0.4,
      responseMimeType: 'application/json',
      responseSchema: {
        type: 'OBJECT',
        properties: {
          company: str, title: str, location: str,
          fit_score: { type: 'INTEGER' },
          verdict: str, summary: str,
          matched_skills: list, missing_skills: list, talking_points: list,
          cover_letter: str,
        },
        required: ['company', 'title', 'location', 'fit_score', 'verdict', 'summary',
                   'matched_skills', 'missing_skills', 'talking_points', 'cover_letter'],
      },
    },
  },
} }];

// Parse Gemini's JSON answer and shape it into the arguments of app.save_analysis.
const job = $('Clean Job Text').first().json;
const resume = $('Get Active Resume').first().json;
const model = $('Build Gemini Request').first().json.model;
const res = $input.first().json || {};
const raw = res?.candidates?.[0]?.content?.parts?.map((p) => p.text || '').join('') || '';

let ai;
try {
  ai = JSON.parse(raw.replace(/^```(json)?/i, '').replace(/```$/, '').trim());
} catch (e) {
  throw new Error('Gemini did not return valid JSON. Try again.');
}

// Trims, drops "Unknown", and keeps within the column length limits.
const clean = (v, fallback = null, max = 200) => {
  const s = String(v ?? '').trim();
  const out = s && s.toLowerCase() !== 'unknown' ? s : fallback;
  return out == null ? null : String(out).slice(0, max);
};
const arr = (v, max) => (Array.isArray(v) ? v : [])
  .map((x) => String(x).trim()).filter(Boolean).slice(0, max);

const score = Math.max(0, Math.min(100, Math.round(Number(ai.fit_score) || 0)));

// The database accepts only these four verdicts; otherwise pick the one that matches the score.
const VERDICTS = ['Strong fit', 'Good fit', 'Stretch', 'Weak fit'];
const verdict = VERDICTS.find((v) => v.toLowerCase() === String(ai.verdict || '').trim().toLowerCase())
  || (score >= 85 ? 'Strong fit' : score >= 70 ? 'Good fit' : score >= 50 ? 'Stretch' : 'Weak fit');

return [{ json: {
  p_user_id: job.user_id,
  p_job_posting_id: job.job_posting_id,
  p_source_url: job.url,
  p_input_method: job.input_method,
  p_company: clean(ai.company, job.hints?.company || 'Unknown company'),
  p_title: clean(ai.title, job.hints?.title || 'Untitled role', 300),
  p_location: clean(ai.location, job.hints?.location),
  p_description: job.text,
  p_fit_score: score,
  p_verdict: verdict,
  p_summary: clean(ai.summary, '', 2000),
  p_matched_skills: arr(ai.matched_skills, 12),
  p_missing_skills: arr(ai.missing_skills, 10),
  p_talking_points: arr(ai.talking_points, 5),
  p_cover_letter: String(ai.cover_letter || '').trim().slice(0, 20000),
  p_resume_id: resume.id,
  p_ai_model: model,
} }];
